import{c as s,$ as a,Q as o,j as i,g as l,o as r,n,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Заказ-наряды","description":"Практическое руководство по ведению заказ-нарядов мастерской в ОмниКрафт ЕРП — учет этапов ремонта, фиксация авансов, списание расходников и интеграция с кассой ДДС.","frontmatter":{"title":"Заказ-наряды","description":"Практическое руководство по ведению заказ-нарядов мастерской в ОмниКрафт ЕРП — учет этапов ремонта, фиксация авансов, списание расходников и интеграция с кассой ДДС.","datePublished":"2026-11-15","dateModified":"2026-11-25","order":12},"headers":[],"relativePath":"ru/docs/spaces/services/orders.md","filePath":"ru/docs/spaces/services/orders.md","lastUpdated":1795564800000}'),c={name:"ru/docs/spaces/services/orders.md"},g={id:"заказ-наряды-рабочии-стол-заказов-и-этапы-выполнения",tabindex:"-1"};function p(h,t,m,u,f,x){const e=a("DocIcon");return o(),i("div",null,[l("h1",g,[r(e,{name:"terms"}),t[0]||(t[0]=n(" Заказ-наряды: Рабочий стол заказов и этапы выполнения ",-1)),t[1]||(t[1]=l("a",{class:"header-anchor",href:"#заказ-наряды-рабочии-стол-заказов-и-этапы-выполнения","aria-label":'Permalink to "Заказ-наряды: Рабочий стол заказов и этапы выполнения"'},"​",-1))]),t[2]||(t[2]=d('<p>В сервисной мастерской рабочий стол заказ-нарядов выполняет роль цифрового диспетчера. В отличие от конвейерного выпуска готовой продукции, где партии однотипны, каждый ремонтный заказ уникален: у него свой заказчик, свой анамнез поломки, индивидуальный набор запчастей и плавающий срок готовности.</p><p>Когда наряды ведутся на бумажных квитанциях или во временных чатах, мастерская регулярно сталкивается с организационными провалами: мастер забывает, какую предоплату внес заказчик, при разборке вскрываются непредвиденные поломки без согласования сметы, а списанные со склада запчасти растворяются в общей куче.</p><p>В <strong>ОмниКрафт ЕРП</strong> вкладка <strong>«Заказы»</strong> объединяет все технологические и финансовые потоки сервиса в единую точку правды. Каждый наряд связывает конкретного заказчика, перечень услуг, складские комплектующие и кассовые ордера в неразрывную цепочку.</p><hr><h2 id="анатомия-карточки-заказ-наряда" tabindex="-1">Анатомия карточки заказ-наряда <a class="header-anchor" href="#анатомия-карточки-заказ-наряда" aria-label="Permalink to &quot;Анатомия карточки заказ-наряда&quot;">​</a></h2><p>Каждый принятый в мастерскую заказ отображается на рабочем столе в виде компактной карточки со всеми ключевыми метриками:</p><ul><li><strong>Идентификатор наряда:</strong> Уникальный серийный номер (например, <code>ORD-0001</code>), который автоматически генерируется системой и проставляется во всех сопутствующих кассовых чеках и отчетах.</li><li><strong>Статусный индикатор:</strong> Наглядный цветовой маркер текущего состояния заказа: <ul><li><code>NEW</code> — наряд зарегистрирован, оборудование принято на ответственное хранение;</li><li><code>IN_PROGRESS</code> — инструмент находится в работе у специалиста;</li><li><code>COMPLETED</code> — работа выполнена, проверена ОТК, полностью оплачена и закрыта (спокойный зеленый индикатор);</li><li><code>CANCELLED</code> — отмененный наряд с проведением возврата средств (красный индикатор).</li></ul></li><li><strong>Сведения о заказе и клиенте:</strong> Тема заказа (<em>«ТО перфоратора: ревизия редуктора и щеток»</em>) и имя заказчика из клиентской базы.</li><li><strong>Финансовый баланс сделки:</strong> Согласованная общая сумма заказа (<code>Итоговая сумма</code>) и фактически принятая предоплата (<code>Предоплата (аванс)</code>).</li><li><strong>Панель быстрых действий:</strong> Кнопка завершения наряда (иконка зеленой галочки) и кнопка отмены (красный крестик).</li></ul><hr><h2 id="предварительные-условия-для-регистрации-наряда" tabindex="-1">Предварительные условия для регистрации наряда <a class="header-anchor" href="#предварительные-условия-для-регистрации-наряда" aria-label="Permalink to &quot;Предварительные условия для регистрации наряда&quot;">​</a></h2><p>Перед оформлением сервисного наряда рекомендуется завести:</p><ol><li><strong>Карточку клиента:</strong> в разделе <strong>«Клиенты»</strong> внесён заказчик с контактным телефоном для оперативного согласования скрытых дефектов;</li><li><strong>Каталог услуг и часовые ставки:</strong> в разделе <strong>«Каталог услуг»</strong> зафиксированы типовые работы и нормо-часы;</li><li><strong>Расходные запчасти на складе:</strong> в разделе <strong>«Материалы»</strong> оприходованы типовые расходники (подшипники, щетки, смазка) для списания в процессе ремонта.</li></ol><hr><h2 id="пошаговое-руководство-регистрация-нового-заказ-наряда" tabindex="-1">Пошаговое руководство: Регистрация нового заказ-наряда <a class="header-anchor" href="#пошаговое-руководство-регистрация-нового-заказ-наряда" aria-label="Permalink to &quot;Пошаговое руководство: Регистрация нового заказ-наряда&quot;">​</a></h2><p>Оформление заказа происходит в момент передачи оборудования или согласования сервисных работ.</p><ol><li>Перейдите во вкладку <strong>«Заказы»</strong> и нажмите кнопку <strong>«Новый заказ-наряд»</strong> в верхнем правом углу.</li><li>В появившемся диалоговом окне укажите параметры заказа: <ul><li><strong>«Описание заказа»:</strong> Четкая формулировка задачи (<em>«Диагностика и устранение биения патрона фрезера»</em>);</li><li>В поле <strong>«Клиент»</strong> введите имя заказчика.</li><li><strong>«Итоговая сумма»:</strong> Полная согласованная стоимость ремонта с учетом предварительно оцененных запасных частей;</li><li><strong>«Предоплата (аванс)»:</strong> Фактическая сумма задатка, внесенная клиентом при оформлении.</li></ul></li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Как сохраняется аванс</p><p>Если указан аванс, например 2 000 ₽, программа сохраняет наряд вместе с приходной записью на вкладке <strong>«ДДС»</strong>. В записи указан номер наряда. Если проводка не сохранилась, форма остаётся открытой и показывает ошибку.</p></div><hr><h2 id="работа-с-заказом-в-мастерскои-этапы-и-расходники" tabindex="-1">Работа с заказом в мастерской: Этапы и расходники <a class="header-anchor" href="#работа-с-заказом-в-мастерскои-этапы-и-расходники" aria-label="Permalink to &quot;Работа с заказом в мастерской: Этапы и расходники&quot;">​</a></h2><p>Когда наряд открыт, мастер приступает к дефектовке и разборке узла. В процессе обслуживания заказ проходит через два ключевых контура учета:</p><h3 id="_1-списание-запчастеи-и-материалов-со-склада" tabindex="-1">1. Списание запчастей и материалов со склада <a class="header-anchor" href="#_1-списание-запчастеи-и-материалов-со-склада" aria-label="Permalink to &quot;1. Списание запчастей и материалов со склада&quot;">​</a></h3><p>Все устанавливаемые комплектующие (подшипники, щетки, сальники, шестерни) и техническая химия (смазка, очистители) списываются с баланса мастерской через вкладку <strong>«Материалы»</strong>:</p><ul><li>Выберите нужную номенклатуру со склада;</li><li>Укажите фактическое списанное количество;</li><li>В примечании сошлитесь на номер текущего наряда.</li></ul><p>Списание выполняется методом скользящей средней стоимости (МАК). Это защищает мастерскую от искажения финансового результата, если разные партии закупались по разным ценам.</p><h3 id="_2-формирование-фактическои-себестоимости-наряда" tabindex="-1">2. Формирование фактической себестоимости наряда <a class="header-anchor" href="#_2-формирование-фактическои-себестоимости-наряда" aria-label="Permalink to &quot;2. Формирование фактической себестоимости наряда&quot;">​</a></h3><p>Программа автоматически рассчитывает плановую и фактическую себестоимость каждого заказа:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Себестоимость наряда</span><div class="formula-heading">Структура прямых и косвенных затрат ремонта</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Себестоимость</span><span class="math-op">=</span><span class="math-num">Стоимость расходников</span><span class="math-op">+</span><span class="math-num">(Нормо-часы × Ставка)</span><span class="math-op">+</span><span class="math-num">Накладные расходы</span></div></div></div><div class="tip custom-block"><p class="custom-block-title">Совет мастера: Согласование скрытых дефектов до закупки деталей</p><p>Если при вскрытии механизма обнаружен критический износ редукторной пары, стоимость которой удваивает предварительную смету, немедленно приостановите работы. Согласуйте с заказчиком новую итоговую сумму через мессенджер из карточки клиента и скорректируйте поле «Итоговая сумма» в наряде. Мастерская никогда не должна оплачивать непредвиденные запчасти из собственного кармана.</p></div><hr><h2 id="завершение-наряда-и-окончательныи-расчет" tabindex="-1">Завершение наряда и окончательный расчет <a class="header-anchor" href="#завершение-наряда-и-окончательныи-расчет" aria-label="Permalink to &quot;Завершение наряда и окончательный расчет&quot;">​</a></h2><p>После завершения слесарных операций, сборки и успешного тестирования под рабочей нагрузкой изделие передается клиенту.</p><ol><li>Найдите заказ в списке и нажмите кнопку <strong>«Завершить заказ»</strong> (зеленая галочка).</li><li>Система запросит подтверждение: <em>«Завершить заказ и провести окончательный расчет в кассу ДДС?»</em>.</li><li><strong>Что происходит под капотом системы при подтверждении:</strong><ul><li>Программа сверяет общую стоимость заказа и ранее внесенную предоплату, вычисляя остаток к доплате: <code>Остаток = Итоговая сумма − Предоплата</code>;</li><li>В кассу мастерской (вкладка <strong>«ДДС»</strong>) автоматически проводится второй приходный ордер на сумму доплаты со статьей <em>«Окончательная оплата по заказу»</em>;</li><li>Заказ получает статус <code>COMPLETED</code>, фиксирует дату и точное время закрытия;</li><li>В карточке фиксируется финальная себестоимость, а чистая маржа отправляется в аналитические отчеты мастерской.</li></ul></li></ol><hr><h2 id="внештатные-ситуации-отмена-заказа-и-возврат-аванса" tabindex="-1">Внештатные ситуации: Отмена заказа и возврат аванса <a class="header-anchor" href="#внештатные-ситуации-отмена-заказа-и-возврат-аванса" aria-label="Permalink to &quot;Внештатные ситуации: Отмена заказа и возврат аванса&quot;">​</a></h2><p>Если в процессе дефектовки выяснилось, что деталь снята с производства, металл корпуса дал трещину или клиент отказался от дорогостоящего восстановления:</p><ol><li>Нажмите кнопку <strong>«Отменить заказ»</strong> (красный крестик в строке наряда).</li><li>Подтвердите операцию в диалоге: <em>«Вы действительно хотите отменить этот заказ-наряд? Будет выполнен возврат аванса»</em>.</li><li><strong>Финансовое действие программы:</strong><ul><li>Если по заказу ранее был принят аванс, программа автоматически сформирует расходный кассовый ордер в ДДС по статье <em>«Возврат аванса по отмененному заказу»</em>;</li><li>Наряд переходит в статус <code>CANCELLED</code>, исключая мнимый доход из управленческих отчетов.</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">Как фиксируется расчёт</p><p>Если доплата или возврат не сохранились в кассе, наряд остаётся в прежнем состоянии. Повторное завершение сохраняет одну проводку доплаты. Завершить отменённый наряд нельзя.</p></div><hr><h2 id="справочная-матрица-жизненного-цикла-заказ-наряда" tabindex="-1">Справочная матрица жизненного цикла заказ-наряда <a class="header-anchor" href="#справочная-матрица-жизненного-цикла-заказ-наряда" aria-label="Permalink to &quot;Справочная матрица жизненного цикла заказ-наряда&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Статус наряда</th><th style="text-align:left;">Доступные действия в UI</th><th style="text-align:left;">Движение денег (ДДС)</th><th style="text-align:left;">Движение склада</th><th style="text-align:left;">Влияние на прибыль и капитал</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>NEW (Новый)</strong></td><td style="text-align:left;">Редактирование, завершение, отмена</td><td style="text-align:left;">Приход аванса (при наличии)</td><td style="text-align:left;">Движения нет</td><td style="text-align:left;">Фиксация обязательства перед клиентом</td></tr><tr><td style="text-align:left;"><strong>IN_PROGRESS (В работе)</strong></td><td style="text-align:left;">Списание запчастей, отмена</td><td style="text-align:left;">Проводок нет</td><td style="text-align:left;">Списание запчастей по МАК</td><td style="text-align:left;">Рост себестоимости незавершенного ремонта</td></tr><tr><td style="text-align:left;"><strong>COMPLETED (Завершен)</strong></td><td style="text-align:left;">Просмотр истории и акта</td><td style="text-align:left;">Окончательный расчет (доплата)</td><td style="text-align:left;">Списание завершено</td><td style="text-align:left;">Фиксация чистой маржи, прирост капитала</td></tr><tr><td style="text-align:left;"><strong>CANCELLED (Отменен)</strong></td><td style="text-align:left;">Просмотр причины отмены</td><td style="text-align:left;">Расход (возврат аванса клиенту)</td><td style="text-align:left;">Возврат неиспользованных деталей</td><td style="text-align:left;">Обнуление обязательств, возврат ликвидности</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Цеховой совет мастера: Правило 50% аванса при заказных комплектующих</p><p>Если для выполнения сервисного заказа требуется заказывать редкие подшипники или электронные модули у внешнего поставщика, никогда не берите символический аванс «на проезд». Сумма предоплаты должна как минимум на 100% покрывать закупочную стоимость заказных деталей и доставку. В случае невыкупа оборудования клиентом мастерская останется при своих деньгах.</p></div>',40))])}const _=s(c,[["render",p]]);export{y as __pageData,_ as default};
